import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"D0.1 · 产品楔子与真实任务基线","description":"Hearth D0.1 开发增量：一份清晰的产品说明、至少 12 个可验收任务，以及全人工与直接使用 Codex 的两条基线。","frontmatter":{"title":"D0.1 · 产品楔子与真实任务基线","description":"Hearth D0.1 开发增量：一份清晰的产品说明、至少 12 个可验收任务，以及全人工与直接使用 Codex 的两条基线。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-0/d0-1.md","filePath":"delivery/stage-0/d0-1.md","lastUpdated":null}'),s={name:"delivery/stage-0/d0-1.md"};function r(h,a,d,o,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 0 · D0.1 · 1 / 4</p><h1 id="d0-1-·-产品楔子与真实任务基线" tabindex="-1">D0.1 · 产品楔子与真实任务基线 <a class="header-anchor" href="#d0-1-·-产品楔子与真实任务基线" aria-label="Permalink to &quot;D0.1 · 产品楔子与真实任务基线&quot;">​</a></h1><p class="lead">先把“谁在什么场景下为什么使用 Hearth”与可验收的真实任务集固定下来；后续原型、契约和评测都以它为准。</p><p class="page-meta">STAGE 0 · D0.1 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>一份清晰的产品说明、至少 12 个可验收任务，以及全人工与直接使用 Codex 的两条基线。</div><div><strong>完成门槛</strong>至少 12 个任务有明确输入、产物和验收方式；能说明 Hearth 的独立价值；任务集包含成功、失败、等待审批和需要接管的情况。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>一份清晰的产品说明、至少 12 个可验收任务，以及全人工与直接使用 Codex 的两条基线。</p><p>Stage 0 的产出是产品真相与实现契约。没有真实任务、可点击原型和可重复评测，后续开发会把假设当成事实。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>一个空仓库、可记录的真实工作样本，以及一位愿意持续反馈的首位用户。</li><li>允许观察全人工流程与直接使用 Codex 的基线，不要求系统已经存在。</li><li>本阶段不接入真实发送、支付、删除或系统设置修改。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-首位用户与任务楔子" tabindex="-1">01 · 首位用户与任务楔子 <a class="header-anchor" href="#_01-·-首位用户与任务楔子" aria-label="Permalink to &quot;01 · 首位用户与任务楔子&quot;">​</a></h3><p>只选一位真实用户和一个高频任务族，记录当前替代工具、每周发生次数、人工分钟、最容易出错的环节和可接受的外部风险。示例可以用“独立研究者整理多份资料并产出带引用的报告”，但必须由真实工作记录证明。</p><h3 id="_02-·-真实任务证据包" tabindex="-1">02 · 真实任务证据包 <a class="header-anchor" href="#_02-·-真实任务证据包" aria-label="Permalink to &quot;02 · 真实任务证据包&quot;">​</a></h3><p>建立 fixtures/tasks，每条任务固定输入、目标产物、验收方式、失败样本、风险级别和任务类别。20–30 个候选中至少保留 12 个，并覆盖研究、文档、代码、邮件、日程、网页、数据和桌面八类中的主要类别。</p><h3 id="_03-·-双基线实验" tabindex="-1">03 · 双基线实验 <a class="header-anchor" href="#_03-·-双基线实验" aria-label="Permalink to &quot;03 · 双基线实验&quot;">​</a></h3><p>对同一批任务分别跑全人工和直接使用 Codex，使用同一验收器记录人工分钟、成功率、Token/成本、错误类型、返工次数和用户不满点。不要用不同任务或不同标准证明 Hearth 更好。</p><h3 id="_04-·-价值与停止判断" tabindex="-1">04 · 价值与停止判断 <a class="header-anchor" href="#_04-·-价值与停止判断" aria-label="Permalink to &quot;04 · 价值与停止判断&quot;">​</a></h3><p>写一页产品定义，说明 Hearth 相比直接使用 Codex 多提供了哪一层：持久状态、审批、恢复、审计、产物验证或长期上下文。同时写明非目标、成功指标和继续/停止条件，防止后续用“功能更多”代替真实价值。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>packages/core/src/schema</code> — 领域实体、状态机与失败分类</li><li><code>packages/eventlog</code> — Event Log、投影与 migration</li><li><code>packages/evals</code> — 任务集、runner、评分与人工复核</li><li><code>apps/web</code> — 今日、需要你、产物、设置与任务详情原型</li><li><code>fixtures/tasks</code> — 真实任务样本与失败样本</li><li><code>docs/adr</code> — Build vs Integrate、事件模型与前端投影决策</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>Event</code></td><td>id、type、schemaVersion、occurredAt、actor、subject、causationId、correlationId、payload；只追加，不能覆盖历史。</td></tr><tr><td><code>TaskCardProjection</code></td><td>taskId、title、state、primaryAction、reason、lastEventAt、artifacts、budget；页面不读取数据库字段。</td></tr><tr><td><code>ExecutorEvent</code></td><td>标准化事件、产物引用、structResult、validation、failureClass、recoverable；执行器不直接写主库。</td></tr><tr><td><code>Approval</code></td><td>effectPreview、scope、expiresAt、decision、idempotencyKey；审批绑定真实动作和参数。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:smoke：12</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 个任务可重复跑分</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev：打开桌面与</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 390px</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 手机宽度原型</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-0/d0-1.html">D0.1 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：首位用户与任务楔子、真实任务证据包、双基线实验、价值与停止判断。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“原型状态无法映射”。页面必须显示“页面显示“需要处理”，并记录未识别的 projection 字段和任务 ID。”，然后按“补齐状态映射、更新契约测试，再重新演示原路径。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：至少 12 个任务有明确输入、产物和验收方式；能说明 Hearth 的独立价值；任务集包含成功、失败、等待审批和需要接管的情况。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>产品说明与任务楔子</li><li>12+ 真实任务卡样本</li><li>全人工/Codex 双基线表</li><li>非目标、风险与成功指标</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 至少 12 个任务有明确输入、产物和验收方式；能说明 Hearth 的独立价值；任务集包含成功、失败、等待审批和需要接管的情况。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>原型状态无法映射</td><td>页面显示“需要处理”，并记录未识别的 projection 字段和任务 ID。</td><td>补齐状态映射、更新契约测试，再重新演示原路径。</td></tr><tr><td>真实任务无法验收</td><td>任务保留在候选池，标注原因，不进入开发承诺。</td><td>补清输入、产物或验收方式，或换一个真实任务。</td></tr><tr><td>基线不可比较</td><td>该任务不进入评测集，避免用失真的数据证明价值。</td><td>重新记录人工分钟、成功率、Token 与失败类型。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不先做完整内核再补界面。</li><li>不用文档完成度替代可点击原型与可重复评测。</li><li>不接入真实高风险外部副作用。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/design/">项目设计与取舍</a></li><li><a href="/hearth-os/reference/checklists.html">默认清单</a></li><li><a href="/hearth-os/architecture/domain-model.html">领域模型与协议</a></li><li><a href="/hearth-os/architecture/evaluation.html">评估体系</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-0/d0-2.html">D0.2 · 可点击的端到端产品原型</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const u=e(s,[["render",r]]);export{k as __pageData,u as default};
